    PreferencesCard(store:store),SpacesCard(store:store),
    BalanceCard(store:store,rates:widget.rates,editable:true),PendingRates(store:store,rates:widget.rates),DistributionEditor(store:store),
    Group('Datos del negocio',subtitle:'Configuración de tu perfil financiero',children:[TextField(controller:business,maxLength:100,decoration:InputDecoration(labelText:t('Nombre del negocio'))),TextField(controller:name,maxLength:80,decoration:InputDecoration(labelText:t('Tu nombre'))),SelectField(label:'Tipo de usuario',value:draft['tipoUsuario'] as String? ?? '',optional:true,items:profileTypes,onChanged:(v)=>setState(()=>draft['tipoUsuario']=v)),SelectField(label:'País',value:draft['countryCode'] as String? ?? '',optional:true,items:{for(final c in Catalog.countries)c['code'] as String:'${Catalog.countryName(c['code'] as String)} (${c['code']})'},onChanged:(v)=>setState(()=>draft['countryCode']=v)),CurrencyField(label:'Moneda principal',value:draft['moneda'] as String? ?? store.currency,onChanged:(v)=>setState(()=>draft['moneda']=v)),CurrencyField(label:'Moneda de visualización (opcional)',value:draft['displayCurrency'] as String? ?? '',optional:true,onChanged:(v)=>setState(()=>draft['displayCurrency']=v)),const Text('Cambiar la moneda principal no recalcula los snapshots históricos. Los importes sin equivalencia en la nueva base quedan pendientes.')],actions:[FilledButton.icon(onPressed:()async{draft['nombreNegocio']=business.text.trim();draft['nombreUsuario']=name.text.trim();await store.setProfile({...draft});if(context.mounted)toast(context,'Perfil actualizado');},icon:const Icon(Icons.check),label:const Text('Guardar perfil'))]),
    Group('Datos y modalidad',subtitle:'Espacios independientes; los datos no se mezclan',children:[Text('Moneda principal actual: ${store.currency}')],actions:[FilledButton.tonal(onPressed:()=>store.switchMode('demo'),child:const Text('Explorar datos de ejemplo')),OutlinedButton(onPressed:()=>store.switchMode('beta'),child:const Text('Comenzar desde cero')),TextButton.icon(onPressed:()async{if(await confirm(context,'Restablecer ${store.mode}','Se eliminarán los cambios de esta modalidad en el dispositivo. La otra modalidad se conserva.'))await store.reset();},icon:const Icon(Icons.refresh),label:Text('Restablecer ${store.mode}'))]),
    Group('Respaldo local',subtitle:'Copia e importa el formato de datos de PLATIK sin enviar tus movimientos a un servidor',children:const [],actions:[OutlinedButton.icon(onPressed:()async{await Clipboard.setData(ClipboardData(text:store.exportData()));if(context.mounted)toast(context,'Respaldo copiado. Guárdalo en un lugar privado.');},icon:const Icon(Icons.copy),label:const Text('Copiar respaldo')),TextButton(onPressed:importBackup,child:const Text('Importar respaldo'))]),
