class DistributionEditor extends StatefulWidget{
  const DistributionEditor({super.key,required this.store});final PlatikStore store;
  @override State<DistributionEditor> createState()=>_DistributionEditorState();
}
class _DistributionEditorState extends State<DistributionEditor>{
  late List<RowData> draft;String saved='';String addKey='';double? previousAvailable;String? previousCurrency;
  final percentages=<String,TextEditingController>{},amounts=<String,TextEditingController>{};
  @override void initState(){super.initState();load(widget.store.distribution);saved=jsonEncode(widget.store.distribution);}
  @override void didUpdateWidget(covariant DistributionEditor old){super.didUpdateWidget(old);if(saved!=jsonEncode(widget.store.distribution)){saved=jsonEncode(widget.store.distribution);load(widget.store.distribution);}else if(previousAvailable!=available||previousCurrency!=widget.store.currency){for(final r in draft){amounts[r['key']]!.text=available>0?rounded(available*number(r['porcentaje'])/100,widget.store.currency).toString():'';}}previousAvailable=available;previousCurrency=widget.store.currency;}
  void load(List<RowData> value){for(final c in [...percentages.values,...amounts.values]){c.dispose();}percentages.clear();amounts.clear();draft=rows(clone(value));for(final item in draft){controllers(item);}}
  void controllers(RowData item){final key=item['key'] as String;percentages[key]=TextEditingController(text:number(item['porcentaje']).toString());amounts[key]=TextEditingController(text:available>0?rounded(available*number(item['porcentaje'])/100,widget.store.currency).toString():'');}
  double get available=>math.max(widget.store.balance.amount??0,0);
  @override void dispose(){for(final c in [...percentages.values,...amounts.values]){c.dispose();}super.dispose();}
  void setPercent(RowData item,String text){final n=double.tryParse(text.replaceAll(',','.'));setState((){item['porcentaje']=n??-1;amounts[item['key']]!.text=n!=null&&n>=0&&available>0?rounded(available*n/100,widget.store.currency).toString():'';});}
  void setAmount(RowData item,String text){final n=double.tryParse(text.replaceAll(',','.'));setState((){final amount=rounded(n??0,widget.store.currency);final percent=available>0?(amount/available*100000-1e-9).ceil()/1000:0.0;item['porcentaje']=percent;percentages[item['key']]!.text=percent.toString();});}
  Future<void> recommend()async{
    final proposed=Catalog.defaults(widget.store.profile['tipoUsuario'] as String?);
    final distribution=available>0?distributionAmounts(proposed,available,widget.store.currency):null;
    final result=await showDialog<String>(context:context,builder:(context)=>AlertDialog(title:const Text('Distribución recomendada'),content:SingleChildScrollView(child:Column(mainAxisSize:MainAxisSize.min,crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Propuesta para ${profileTypes[widget.store.profile['tipoUsuario']]??'usuario general'}. Reglas transparentes y porcentajes de referencia editables.'),const SizedBox(height:12),for(final item in proposed)Padding(padding:const EdgeInsets.only(top:8),child:Text('${item['nombre']}: ${pct(number(item['porcentaje']),0)}${distribution==null?'':' · ${money(number(distribution['porCategoria'][item['key']]),widget.store.currency)}'}')),const SizedBox(height:12),Text(available>0?'Calculado sobre ${money(available,widget.store.currency)} disponibles.':'No hay dinero disponible positivo: los porcentajes son una referencia.'),const SizedBox(height:8),const Text('Revisa y confirma la propuesta. PLATIK no da asesoría financiera personalizada.')])),actions:[TextButton(onPressed:()=>Navigator.pop(context,'reject'),child:const Text('Rechazar')),TextButton(onPressed:()=>Navigator.pop(context,'recalculate'),child:const Text('Recalcular')),OutlinedButton(onPressed:()=>Navigator.pop(context,'edit'),child:const Text('Modificar')),FilledButton(onPressed:()=>Navigator.pop(context,'apply'),child:const Text('Aplicar'))]));
    if(!mounted)return;if(result=='recalculate'){await recommend();return;}if(result=='edit'){setState(()=>load(proposed));}else if(result=='apply'){await widget.store.patch({'distribution':proposed});if(mounted)toast(context,'Distribución recomendada aplicada.');}
  }
  @override Widget build(BuildContext context){final total=draft.fold<double>(0,(s,r)=>s+number(r['porcentaje']));final valid=draft.every((r)=>number(r['porcentaje'])>=0&&number(r['porcentaje'])<=100)&&total<=100+1e-9;final missing=Catalog.distribution.where((r)=>!draft.any((d)=>d['key']==r['key'])).toList();return Group('Distribución del dinero disponible',subtitle:'Edita porcentaje o monto; ambos se mantienen sincronizados',children:[Text('Base: ${widget.store.balance.amount==null?'saldo no determinable':money(available,widget.store.currency)}',style:body(13)),for(final item in draft)Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Row(children:[Expanded(child:Text(item['nombre'] as String,style:body(14,w:FontWeight.w800))),IconButton(tooltip:t('Quitar categoría'),onPressed:()=>setState((){draft.remove(item);percentages.remove(item['key'])?.dispose();amounts.remove(item['key'])?.dispose();}),icon:const Icon(Icons.close,size:18))]),Text(item['descripcion'] as String? ?? '',style:body(11,color:C.sub)),const SizedBox(height:8),Row(children:[Expanded(child:TextField(controller:percentages[item['key']],keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:InputDecoration(labelText:t('Porcentaje'),suffixText:'%'),onChanged:(v)=>setPercent(item,v))),const SizedBox(width:10),Expanded(child:TextField(controller:amounts[item['key']],enabled:available>0,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:InputDecoration(labelText:t('Monto'),suffixText:widget.store.currency),onChanged:(v)=>setAmount(item,v)))]),const Divider()]),if(missing.isNotEmpty)...[SelectField(label:'Agregar categoría',value:addKey,items:{'':'Elige una categoría',for(final item in missing)item['key'] as String:item['nombre'] as String},onChanged:(v)=>setState(()=>addKey=v)),OutlinedButton.icon(onPressed:addKey.isEmpty?null:()=>setState((){final item={...missing.firstWhere((r)=>r['key']==addKey),'porcentaje':0};draft.add(item);controllers(item);addKey='';}),icon:const Icon(Icons.add),label:const Text('Agregar categoría'))],Text('Total asignado: ${pct(total,3)} · Sin asignar: ${pct(math.max(0,100-total),3)}',style:body(13,color:valid?C.petroleum:Colors.red.shade800)),if(!valid)Text('Cada porcentaje debe estar entre 0 y 100, y la suma no puede superar 100%.',style:body(12,color:Colors.red.shade800))],actions:[TextButton.icon(onPressed:recommend,icon:const Icon(Icons.auto_awesome_outlined),label:const Text('Recomendar')),TextButton(onPressed:()=>setState(()=>load(Catalog.defaults(widget.store.profile['tipoUsuario'] as String?))),child:const Text('Restablecer')),FilledButton(onPressed:valid?()async{await widget.store.patch({'distribution':rows(clone(draft))});if(context.mounted)toast(context,'Distribución actualizada.');}:null,child:const Text('Guardar distribución'))]);}
}

class OnboardingPage extends StatefulWidget{
  const OnboardingPage({super.key,required this.store,required this.rates});final PlatikStore store;final RateService rates;
  @override State<OnboardingPage> createState()=>_OnboardingPageState();
}
class _OnboardingPageState extends State<OnboardingPage>{
  String option='',country='',currency='',display='',type='',date=today();bool opening=false,busy=false;final amount=TextEditingController();String? error;
  @override void dispose(){amount.dispose();super.dispose();}
  Future<void> saveCurrency()async{await widget.store.setProfile({...widget.store.profile,'countryCode':country,'moneda':currency,'displayCurrency':display,'onboardingOption':option,'currencyPreference':option=='bolivia'?'local':option=='usd'?'usd':'custom','onboardingDone':true});}
  Future<void> saveProfile(bool skip)async{
    if(type.isEmpty){setState(()=>error='Elige tu tipo de usuario.');return;}
    final n=double.tryParse(amount.text.replaceAll(',','.'));if(opening&&!skip&&(n==null||!n.isFinite||n<=0||rounded(n,currency.isEmpty?widget.store.currency:currency)<=0)){setState(()=>error='Ingresa un saldo inicial positivo válido.');return;}
    setState((){busy=true;error=null;});
    try{final c=currency.isEmpty?widget.store.currency:currency;final conversion=opening&&!skip?await widget.rates.conversion(c,widget.store.currency,rounded(n!,c)):<String,dynamic>{};await widget.store.patch({'profile':{...widget.store.profile,'tipoUsuario':type,'betaSetupDone':true},'openingBalance':opening&&!skip?{'id':newId(),'monto':rounded(n!,c),'moneda':c,'fecha':date,'descripcion':'Saldo de apertura',...conversion}:null,'distribution':Catalog.defaults(type)});}catch(e){if(mounted)setState(()=>error=e.toString());}finally{if(mounted)setState(()=>busy=false);}
  }
  @override Widget build(BuildContext context){final needsCurrency=widget.store.profile['onboardingDone']!=true;return PageBody(title:needsCurrency?'¿Cómo manejas tu dinero?':'Bienvenido/a a PLATIK BETA',subtitle:needsCurrency?'Elige una opción para empezar. Podrás cambiarla en Perfil.':'Configura tu perfil y tu punto de partida.',children:[
    if(needsCurrency)...[
      for(final choice in [('bolivia','Manejo bolivianos','Usar BOB y el país Bolivia'),('usd','Trabajo en dólares','Usar USD como moneda principal'),('world','Mi dinero en el mundo','Elegir país y moneda del catálogo internacional')])Paper(color:option==choice.$1?C.highlight:C.card,onTap:()=>setState((){option=choice.$1;country=option=='bolivia'?'BO':'';currency=option=='bolivia'?'BOB':option=='usd'?'USD':'';}),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(choice.$2,style:h(18)),Text(choice.$3,style:body(13,color:C.sub))])),
      if(option.isNotEmpty)Group('País y monedas',children:[SelectField(label:'País',value:country,optional:true,items:{for(final c in Catalog.countries)c['code'] as String:'${Catalog.countryName(c['code'] as String)} (${c['code']})'},onChanged:(v)=>setState((){country=v;final currencies=Catalog.countries.where((c)=>c['code']==v).firstOrNull?['currencies'] as List? ?? [];if(currencies.isNotEmpty)currency=currencies.first as String;})),CurrencyField(label:'Moneda principal',value:currency,onChanged:(v)=>setState(()=>currency=v)),CurrencyField(label:'Moneda de visualización (opcional)',value:display,optional:true,onChanged:(v)=>setState(()=>display=v))],actions:[FilledButton(onPressed:currency.isEmpty?null:saveCurrency,child:const Text('Comenzar'))]),
    ]else ...[
      for(final entry in profileTypes.entries)Paper(color:type==entry.key?C.highlight:C.card,onTap:busy?null:()=>setState(()=>type=entry.key),child:Row(children:[Expanded(child:Text(entry.value,style:body(15))),if(type==entry.key)const Icon(Icons.check_circle,color:C.petroleum)])),
      Group('¿Tienes dinero disponible ahora?',children:[SwitchListTile(contentPadding:EdgeInsets.zero,title:const Text('Registrar saldo inicial'),subtitle:const Text('Se registra como saldo de apertura, no como ingreso.'),value:opening,onChanged:busy?null:(v)=>setState(()=>opening=v)),if(opening)...[TextField(controller:amount,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:InputDecoration(labelText:t('Saldo inicial'))),CurrencyField(value:currency.isEmpty?widget.store.currency:currency,onChanged:(v)=>setState(()=>currency=v)),DateField(label:'Fecha de apertura',value:date,onChanged:(v)=>setState(()=>date=v))],if(error!=null)Text(error!,style:TextStyle(color:Colors.red.shade800))],actions:[TextButton(onPressed:busy?null:()=>saveProfile(true),child:const Text('Continuar sin saldo')),FilledButton(onPressed:busy?null:()=>saveProfile(false),child:Text(busy?'Guardando…':'Comenzar'))]),
      const Notice('La prueba beta es de 72 horas; el tiempo restante se informa por separado. La demo siempre está disponible.'),
    ]
  ]);}
}
